class Solution {
    public boolean checkEqualTree(TreeNode root) {
        List<Long> seen = new ArrayList<>();
        long total = getSum(root, seen);
        seen.remove(seen.size() - 1);
        if (total % 2 != 0) return false;
        long target = total / 2;
        for (long s : seen) {
            if (s == target) return true;
        }
        return false;
    }

    private long getSum(TreeNode node, List<Long> seen) {
        if (node == null) return 0;
        long s = node.val + getSum(node.left, seen) + getSum(node.right, seen);
        seen.add(s);
        return s;
    }
}

var checkEqualTree = function(root) {
    const seen = [];

    function getSum(node) {
        if (!node) return 0;
        const s = node.val + getSum(node.left) + getSum(node.right);
        seen.push(s);
        return s;
    }

    const total = getSum(root);
    seen.pop();
    if (total % 2 !== 0) return false;
    const target = total / 2;
    return seen.includes(target);
};
